        if d_in[r,c] != 0 and d_out[r,c] != 0:
            # This cell kept its value
            print(f"({r},{c}): {d_in[r,c]} -> {d_out[r,c]}")

# Calculate distances from each cell to the 2x2 zero block
zero_block = set([(6,8),(6,9),(7,8),(7,9)])

def manhattan_dist(r, c, zero_block):
    """Calculate min Manhattan distance to any zero in the block"""
    min_dist = float('inf')
    for zr, zc in zero_block:
        dist = abs(r - zr) + abs(c - zc)
        min_dist = min(min_dist, dist)
    return min_dist

distances = {}
for r in range(20):
    for c in range(20):
        d = manhattan_dist(r, c, zero_block)
        distances[(r,c)] = d

# Check cells that became 0 vs stayed non-zero
changed_to_zero = []
stayed_nonzero = []

for r in range(20):
    for c in range(20):
        orig_val = demo_input[r][c]
        new_val = demo_output[r][c]

        if orig_val != 0 and new_val == 0:
            changed_to_zero.append((r, c))
        elif orig_val != 0 and new_val != 0:
            stayed_nonzero.append((r, c))

print(f"Changed to 0: {len(changed_to_zero)}")
print(f"Stayed nonzero: {len(stayed_nonzero)}")

